"""Shailaputri v1 (SMD) `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    onset = r["params"]["onset"]
    out = [
        "<!-- Generated by packages/sati/sati/detect/smdreport.py from the training workflow. Do not edit by hand. -->\n",
        "# Shailaputri v1 — anomaly detection across a server's metrics (SMD)\n",
        f"**{d['name']}** ({d['repo']} @ `{d['revision'][:12]}`): {d['machines']} real servers × "
        f"{d['metrics_per_machine']} metrics, {d['test_minutes']:,} labelled test minutes holding {d['anomalies']} "
        f"anomalies. Each machine group ({', '.join(f'`{g}`' for g in d['groups'])}) is held out in turn; the model "
        "and every threshold are chosen on the other groups. Every detector is scored online by the same harness "
        "(`pashupatastra.evaluation.evaluate`) on exactly the same minutes.\n",
        "Recall is per anomaly *episode*; precision is per flagged minute; false alarms are per 1000 minutes; lead "
        "is how many minutes before the anomaly's end the first flag came (higher is earlier). Not point-adjusted.\n",
        "## Mean across held-out machine groups\n",
        "| Detector | F1 | Precision | Episode recall | False alarms / 1000 | Lead |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for name, m in r["mean_across_groups"].items():
        label = f"**{name}**" if name.startswith("shailaputri") else name
        out.append(f"| {label} | {m['f1']:.3f} | {m['precision']:.3f} | {m['recall']:.3f} | "
                   f"{m['false_alarms_per_1000']:.1f} | {m['mean_lead']:.1f} |")
    out += ["", "## Per held-out group\n", "| Held out | Machines | Detector | F1 | Recall | FA / 1000 | Lead |",
            "|---|---:|---|---:|---:|---:|---:|"]
    for f in r["folds"]:
        for name, m in f["detectors"].items():
            out.append(f"| `{f['held_out']}` | {f['machines']} | {name} | {m['f1']:.3f} | {m['recall']:.3f} | "
                       f"{m['false_alarms_per_1000']:.1f} | {m['mean_lead']:.1f} |")
    out += [
        "",
        "## How to read this\n",
        f"- *Onset-weighted* gives the first {onset['share']:.0%} of each labelled anomaly (at least {onset['min']} "
        f"minutes) {onset['weight']:g}× the training weight. Compare its lead with the unweighted row to see whether "
        "that bought earlier flags, and its false alarms to see what it cost.",
        "- *PCA per machine* is fitted on each machine's own unlabelled first half, so it has seen the held-out "
        "machines' normal behaviour; the learned model has not. That favours the baseline.",
        "- Read F1 together with false alarms per 1000: a detector that flags everything catches every episode.",
        "- Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
